/** Every entry of the range, newest first, gathered page by page. */
export async function collectActivity(
  input: Pick<ExportActivityInput, "orgId" | "since" | "until">,
): Promise<readonly ActivityEvent[]> {
  assertRange(input.since, input.until);
  const items: ActivityEvent[] = [];
  const seen = new Set<string>();
  let cursor: string | null = null;
  do {
    const page: Page<ActivityEvent> = await activityRepo.listActivity({
      orgId: input.orgId,
      since: input.since,
      until: input.until,
      limit: 100,
      cursor,
    });
    for (const item of page.items) {
      if (!seen.has(item.id)) {
        seen.add(item.id);
        items.push(item);
      }
    }
    cursor = page.nextCursor;
  } while (cursor !== null);
  return items;
}

