i=s.index("export function registerActivityListeners")
head=s[:i]
new='''export function registerActivityListeners(): Unsubscribe {
  const on = <K extends TaskflowEventType>(
    type: K,
    build: (
      payload: TaskflowEventPayload<K>,
    ) => ActivityRecordInput | Promise<ActivityRecordInput>,
  ): Unsubscribe =>
    subscribe(type, async (payload) => {
      const input = await build(payload);
      await record(payload.orgId, type as ActivityAction, {
        ...input,
        occurredAt: input.occurredAt ?? payload.occurredAt,
        actorId: input.actorId,
      });
    });

  const commentProject = async (payload: {
    orgId: OrgId;
    issueId: IssueId;
    projectId?: ProjectId;
  }): Promise<ProjectId | null> => {
    if (payload.projectId !== undefined) return payload.projectId;
    const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
    return issue?.projectId ?? null;
  };

  const offs: Unsubscribe[] = [
    on("project.created", (payload) => ({
      actorId: payload.actorId,
      subjectKind: "project",
      subjectId: payload.projectId,
      projectId: payload.projectId,
      summary: `Created project ${payload.name}`,
    })),
    on("project.updated", (payload) => ({
      actorId: payload.actorId,
      subjectKind: "project",
      subjectId: payload.projectId,
      projectId: payload.projectId,
      summary: `Updated project (${payload.changedFields.join(", ")})`,
    })),
    on("project.archived", (payload) => ({
      actorId: payload.actorId,
      subjectKind: "project",
      subjectId: payload.projectId,
      projectId: payload.projectId,
      summary: `Archived project with ${payload.issuesArchived} issues`,
    })),
    on("project.restored", (payload) => ({
      actorId: payload.actorId,
      subjectKind: "project",
      subjectId: payload.projectId,
      projectId: payload.projectId,
      summary: "Restored project",
    })),
    on("issue.created", (payload) => ({
      actorId: payload.actorId,
      subjectKind: "issue",
      subjectId: payload.issueId,
      projectId: payload.projectId,
      summary: `Created issue "${payload.title}"`,
      metadata: { priority: payload.priority },
    })),
    on("issue.updated", (payload) => ({
      actorId: payload.actorId,
      subjectKind: "issue",
      subjectId: payload.issueId,
      projectId: payload.projectId,
      summary: `Updated issue (${payload.changedFields.join(", ")})`,
    })),
    on("issue.status_changed", (payload) => ({
      actorId: payload.actorId,
      subjectKind: "issue",
      subjectId: payload.issueId,
      projectId: payload.projectId,
      summary: `Status ${payload.from} → ${payload.to}`,
      metadata: { from: payload.from, to: payload.to },
    })),
    on("issue.assigned", (payload) => ({
      actorId: payload.actorId,
      subjectKind: "issue",
      subjectId: payload.issueId,
      projectId: payload.projectId,
      summary: `Assigned to ${payload.assigneeId}`,
      metadata: {
        assigneeId: payload.assigneeId,
        previousAssigneeId: payload.previousAssigneeId,
      },
    })),
    on("issue.archived", (payload) => ({
      actorId: payload.actorId,
      subjectKind: "issue",
      subjectId: payload.issueId,
      projectId: payload.projectId,
      summary: "Archived issue",
    })),
    on("comment.created", async (payload) => ({
      actorId: payload.actorId,
      subjectKind: "comment",
      subjectId: payload.commentId,
      projectId: await commentProject(payload),
      summary: `Commented on issue ${payload.issueId}`,
    })),
    on("comment.updated", async (payload) => ({
      actorId: payload.actorId,
      subjectKind: "comment",
      subjectId: payload.commentId,
      projectId: await commentProject(payload),
